    ui:HTMLElement;hud:HTMLElement;dialogLayer:HTMLElement;stage:HTMLElement;tip:HTMLElement;toastElement:HTMLElement;canvas:HTMLCanvasElement;
    keys=new Set<string>();path:{x:number;y:number}[]=[];clickEntity:Entity|null=null;near:Entity|null=null;last=0;stepTime=0;autoTime=0;hudTime=0;cooldown=0;hazardTime=0;toastTime=0;zoneTime=0;
