      let storage:StorageLike;try{const test='lantern-tides:probe';localStorage.setItem(test,'1');localStorage.removeItem(test);storage=localStorage;}catch{this.storageAvailable=false;const memory=new Map<string,string>();storage={getItem:k=>memory.get(k)??null,setItem:(k,v)=>{memory.set(k,v);},removeItem:k=>{memory.delete(k);}};}this.store=new SaveStore(storage);
      this.stage.addEventListener('click',e=>{const target=(e.target as HTMLElement).closest<HTMLButtonElement>('button[data-a]');if(target&&!target.disabled){this.audio.start();this.audio.sfx('confirm');this.handle(target.dataset.a||'',target.dataset.id||'');}});
      this.stage.addEventListener('change',e=>this.settingChanged(e));this.stage.addEventListener('input',e=>{const t=e.target as HTMLInputElement;if(t.type==='range')this.settingChanged(e);});
