    speak(lines:Line[],done?:()=>void,choices:Choice[]=[],returnTo:Screen='explore'):void {this.dialogue=lines;this.dialogIndex=0;this.dialogChars=0;this.dialogChoices=choices;this.dialogDone=done||null;this.dialogReturn=returnTo;this.mode='dialog';this.keys.clear();this.path=[];this.ui.innerHTML='';this.renderDialog();this.renderHUD();}
