    finishDialog():void {const done=this.dialogDone;this.dialogDone=null;this.dialogLayer.innerHTML='';this.mode=this.dialogReturn;this.render();if(done)done();}
    renderDialog():void {const line=this.dialogue[this.dialogIndex];if(!line)return;const last=this.dialogIndex===this.dialogue.length-1,complete=this.dialogChars>=line.text.length;
      this.dialogLayer.innerHTML=`<section class="dialog ${line.hero===undefined?'no-face':''}">${line.hero===undefined?'':`<div class="face" style="${faceStyle(line.hero)}"></div>`}<div class="speaker">${esc(line.speaker)}</div><div class="text">${esc(line.text.slice(0,Math.floor(this.dialogChars)))}</div><div class="hint">${last&&this.dialogChoices.length?'选择你的回答':'E / ENTER · 继续　'+(this.dialogIndex+1)+' / '+this.dialogue.length}</div>${last&&this.dialogChoices.length&&complete?'':btn('advance','', '', 'advance')}</section>${last&&complete&&this.dialogChoices.length?`<div class="choices">${this.dialogChoices.map((c,i)=>btn('choice',esc(c.label),String(i),'')).join('')}</div>`:''}`;
    }
    openMenu(name:string):void {if(this.mode==='battle'||this.mode==='result'||this.mode==='dialog')return;this.returnScreen=this.mode==='title'?'title':'explore';this.menu=name;this.mode='menu';this.keys.clear();this.path=[];this.near=null;this.tip.style.display='none';this.selectedHero=this.state.active[0];this.render();this.focusFirst();}
    closeMenu():void {if(this.mode==='select'){this.mode='title';this.render();return;}if(this.mode==='menu'){this.mode=this.returnScreen;this.render();return;}if(this.mode==='explore')this.openMenu('party');else if(this.mode==='dialog')this.advanceDialog();else if(this.mode==='battle'){this.pending=null;this.combatMode='command';this.renderBattle();}}
