      if(this.mode==='dialog'){const line=this.dialogue[this.dialogIndex];if(line&&this.dialogChars<line.text.length){const prev=Math.floor(this.dialogChars);this.dialogChars=Math.min(line.text.length,this.dialogChars+dt*this.state.settings.textSpeed);if(Math.floor(this.dialogChars)!==prev)this.renderDialog();}}
