      if(this.near){const p=this.renderer.screen(this.near.x,this.near.y,55);this.tip.style.display='block';this.tip.style.left=clamp(p.x,135,1145)+'px';this.tip.style.top=clamp(p.y,170,590)+'px';this.tip.textContent='E  '+interactionLabel(this.state,this.near);}else this.tip.style.display='none';
      if(this.clickEntity&&Math.hypot(this.clickEntity.x-this.state.x,this.clickEntity.y-this.state.y)<1.55){const entity=this.clickEntity;this.clickEntity=null;this.path=[];this.interact(entity);return;}
