      if(e.kind==='inn'){if(e.value!=='rest'){this.travel(r,'inn');return;}const cost=24+this.state.bells.length*8;this.speak([{speaker:'旅舍主人',text:'路总是很长，睡一觉再走吧。'+(this.state.gold<cost?'今晚的床位记在我账上。不必让一场疲惫变成你的终点。':`一晚 ${cost} 潮币，所有同行与后备旅人完全恢复。`)}],undefined,[{label:this.state.gold<cost?'接受好意，休息一晚。':`住店 · ${cost} 潮币`,run:()=>{if(this.state.gold>=cost)this.state.gold-=cost;healParty(this.state);for(const key of Object.keys(this.state.flags))if(key.startsWith('enc:'))delete this.state.flags[key];this.audio.sfx('heal');this.autosave();this.toast('天色微明。生命与灵息完全恢复，野外群落重新活动。');this.render();}},{label:'暂时不住。',run:()=>this.render()}]);return;}
